        $_data = array();
        foreach ($data as $k => $d) {
            if (in_array($k, $this->table_columns) === true) {
                $_data[$k] = $d;
            }
        }

        $id = 0;
        if (isset($_data['id']) && $_data['id'] > 0 ) {
            $id = $_data['id'];
        } elseif ( isset($_data['bid_id']) && $_data['bid_id'] > 0 &&
                    isset($_data['model_id']) && $_data['model_id'] > 0) {

            $model = $this->getModelBidAndModel($_data['bid_id'], $_data['model_id']);
