                } else {
                    $_data = $this->superIntegerFixer($_data);
                    $this->where('id', $id)->update($_data);
                }
            }
        } else {
            if (isset($_data['id'])) {
                unset($_data['id']);
            }


            if (isset($_data['deleted']) ) {
                unset($_data['deleted']);
            }

            $models = $this->where('model_id', $_data['model_id'])
                            ->where('bid_id', $_data['bid_id'])
                            ->get()->toArray();

            $_data = $this->superIntegerFixer($_data);

            if (count($models) == 0 ) {
                // Правим косяк !null поля
                if (!isset($_data['merge'])){
                    $_data['merge'] = "";
                }

                $new = new AnBidmodel($_data);
                $new->save();
                $id  = $new->id;
