    public function refreshRateBid($bid_id, $rate)
    {
        // Фиксируем курс если он еще не зафиксирован
        $bid = $this->getBid($bid_id);
        $_data = [];
        if ($bid['rate_usd'] == 0 && isset($rate['rate_usd'])) {
            $_data['rate_usd'] = (float) $rate['rate_usd'];
        }
        if ($bid['rate_euro'] == 0 && isset($rate['rate_euro'])) {
            $_data['rate_euro'] = (float) $rate['rate_euro'];
        }
        if (count($_data) > 0) {
            $this->update($_data, ['id' => $bid_id]);
        }
    }

    /*
    is_replase - true заменять полюбому даже если уже установленно
    */
    public function refreshModelsPrice($bid_id, $is_replase = false)
    {
        $models = $this->getBidModel($bid_id);
        $manbid = new AnBid;
        // $bid = $manbid->getBid($bid_id);
        $bid = current($manbid->where('id', $bid_id)->get()->toArray());

        $manmodels = new AnModels;

        foreach ($models as $m) {
            if ($m['price'] == 0 || $is_replase === true) {
                $model = current($manmodels->getModelId($m['model_id']));
                $price = 0;
                if ($bid['statusmoney_id'] == 1) {
                    $price = $model['price_0'];
                }
                if ($bid['statusmoney_id'] == 2) {
                    $price = $model['price_10'];
                }
                if ($bid['statusmoney_id'] == 3) {
                    $price = $model['price_20'];
                }
                if ($bid['statusmoney_id'] == 4) {
                    $price = $model['price_30'];
                }
                // $price = $price*(1 - $bid['percent']/100);
                // $this->update(array('price' => $price), 'id='.$m['id']);
                $this->where('id', $m['id'])->update(['price' => $price]);
            }
        }
    }

